	@Test
	void independentCursorsPreserveMultiplicityAndOwnerCloseClosesActiveCursor() {
		ScopedEvaluationOwner owner = ScopedEvaluationOwner.root(EmptyBindingSet.getInstance());
		AtomicInteger evaluationCount = new AtomicInteger();
		AtomicInteger producerCloseCount = new AtomicInteger();
		ValueFactory valueFactory = SimpleValueFactory.getInstance();
		BindingSet first = bindingSet("x", valueFactory.createLiteral("same"));
		BindingSet duplicate = bindingSet("x", valueFactory.createLiteral("same"));
		BindingSet last = bindingSet("x", valueFactory.createLiteral("last"));
		List<BindingSet> expected = List.of(first, duplicate, last);
		QueryEvaluationStep producer = bindings -> {
			evaluationCount.incrementAndGet();
			return trackingIteration(expected, producerCloseCount);
		};
		Object occurrence = new Object();

		CloseableIteration<BindingSet> firstCursor = null;
		CloseableIteration<BindingSet> secondCursor = null;
		try {
			firstCursor = owner.openCached(occurrence, producer);
			secondCursor = owner.openCached(occurrence, producer);
			assertTrue(firstCursor.hasNext());
			assertEquals(first, firstCursor.next());
			assertTrue(secondCursor.hasNext());
			assertEquals(first, secondCursor.next());
			assertTrue(firstCursor.hasNext());
			assertEquals(duplicate, firstCursor.next());
			assertTrue(secondCursor.hasNext());
			assertEquals(duplicate, secondCursor.next());
			assertTrue(firstCursor.hasNext());
			assertEquals(last, firstCursor.next());
			assertFalse(firstCursor.hasNext());
			assertEquals(1, evaluationCount.get(), "the occurrence must be produced once");
			assertEquals(1, producerCloseCount.get());

			owner.close();
			assertTrue(owner.isClosed());
			assertFalse(secondCursor.hasNext(), "owner close must close an active replay cursor");
		} finally {
			if (firstCursor != null) {
				firstCursor.close();
			}
			if (secondCursor != null) {
				secondCursor.close();
			}
			owner.close();
		}
	}

